import{_ as e,o as a,c as n,aj as s}from"./chunks/framework.C6uXqnaX.js";const h=JSON.parse('{"title":"Work with translation files","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"guide/i18n/translation-files.md","filePath":"guide/i18n/translation-files.md"}'),l={name:"guide/i18n/translation-files.md"};function i(o,t,r,p,c,d){return a(),n("div",null,t[0]||(t[0]=[s(`<h1 id="work-with-translation-files" tabindex="-1">Work with translation files <a class="header-anchor" href="#work-with-translation-files" aria-label="Permalink to &quot;Work with translation files&quot;">​</a></h1><p>After you prepare a component for translation, use the <a href="./cli/extract-i18n" title="ng extract-i18n | CLI | Angular"><code>extract-i18n</code></a> <a href="./cli" title="CLI Overview and Command Reference | Angular">Angular CLI</a> command to extract the marked text in the component into a <em>source language</em> file.</p><p>The marked text includes text marked with <code>i18n</code>, attributes marked with <code>i18n-</code><em>attribute</em>, and text tagged with <code>$localize</code> as described in <a href="./guide/i18n/prepare" title="Prepare component for translation | Angular">Prepare component for translation</a>.</p><p>Complete the following steps to create and update translation files for your project.</p><ol><li><a href="./guide/i18n/translation-files#extract-the-source-language-file" title="Extract the source language file - Work with translation files | Angular">Extract the source language file</a>. <ol><li>Optionally, change the location, format, and name.</li></ol></li><li>Copy the source language file to <a href="./guide/i18n/translation-files#create-a-translation-file-for-each-language" title="Create a translation file for each language - Work with translation files | Angular">create a translation file for each language</a>.</li><li><a href="./guide/i18n/translation-files#translate-each-translation-file" title="Translate each translation file - Work with translation files | Angular">Translate each translation file</a>.</li><li>Translate plurals and alternate expressions separately. <ol><li><a href="./guide/i18n/translation-files#translate-plurals" title="Translate plurals - Work with translation files | Angular">Translate plurals</a>.</li><li><a href="./guide/i18n/translation-files#translate-alternate-expressions" title="Translate alternate expressions - Work with translation files | Angular">Translate alternate expressions</a>.</li><li><a href="./guide/i18n/translation-files#translate-nested-expressions" title="Translate nested expressions - Work with translation files | Angular">Translate nested expressions</a>.</li></ol></li></ol><h2 id="extract-the-source-language-file" tabindex="-1">Extract the source language file <a class="header-anchor" href="#extract-the-source-language-file" aria-label="Permalink to &quot;Extract the source language file&quot;">​</a></h2><p>To extract the source language file, complete the following actions.</p><ol><li>Open a terminal window.</li><li>Change to the root directory of your project.</li><li>Run the following CLI command.</li></ol><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extract-i18n</span></span></code></pre></div><p>The <code>extract-i18n</code> command creates a source language file named <code>messages.xlf</code> in the root directory of your project. For more information about the XML Localization Interchange File Format (XLIFF, version 1.2), see <a href="https://en.wikipedia.org/wiki/XLIFF" title="XLIFF | Wikipedia" target="_blank" rel="noreferrer">XLIFF</a>.</p><p>Use the following <a href="./cli/extract-i18n" title="ng extract-i18n | CLI | Angular"><code>extract-i18n</code></a> command options to change the source language file location, format, and file name.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Command option</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--format</code></td><td style="text-align:left;">Set the format of the output file</td></tr><tr><td style="text-align:left;"><code>--out-file</code></td><td style="text-align:left;">Set the name of the output file</td></tr><tr><td style="text-align:left;"><code>--output-path</code></td><td style="text-align:left;">Set the path of the output directory</td></tr></tbody></table><h3 id="change-the-source-language-file-location" tabindex="-1">Change the source language file location <a class="header-anchor" href="#change-the-source-language-file-location" aria-label="Permalink to &quot;Change the source language file location&quot;">​</a></h3><p>To create a file in the <code>src/locale</code> directory, specify the output path as an option.</p><h4 id="extract-i18n-output-path-example" tabindex="-1"><code>extract-i18n --output-path</code> example <a class="header-anchor" href="#extract-i18n-output-path-example" aria-label="Permalink to &quot;\`extract-i18n --output-path\` example&quot;">​</a></h4><p>The following example specifies the output path as an option.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extract-i18n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/locale</span></span></code></pre></div><h3 id="change-the-source-language-file-format" tabindex="-1">Change the source language file format <a class="header-anchor" href="#change-the-source-language-file-format" aria-label="Permalink to &quot;Change the source language file format&quot;">​</a></h3><p>The <code>extract-i18n</code> command creates files in the following translation formats.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Translation format</th><th style="text-align:left;">Details</th><th style="text-align:left;">File extension</th></tr></thead><tbody><tr><td style="text-align:left;">ARB</td><td style="text-align:left;"><a href="https://github.com/google/app-resource-bundle/wiki/ApplicationResourceBundleSpecification" title="ApplicationResourceBundleSpecification | google/app-resource-bundle | GitHub" target="_blank" rel="noreferrer">Application Resource Bundle</a></td><td style="text-align:left;"><code>.arb</code></td></tr><tr><td style="text-align:left;">JSON</td><td style="text-align:left;"><a href="https://www.json.org" title="Introducing JSON | JSON" target="_blank" rel="noreferrer">JavaScript Object Notation</a></td><td style="text-align:left;"><code>.json</code></td></tr><tr><td style="text-align:left;">XLIFF 1.2</td><td style="text-align:left;"><a href="https://docs.oasis-open.org/xliff/v1.2/os/xliff-core.html" title="XLIFF Version 1.2 Specification | Oasis Open Docs" target="_blank" rel="noreferrer">XML Localization Interchange File Format, version 1.2</a></td><td style="text-align:left;"><code>.xlf</code></td></tr><tr><td style="text-align:left;">XLIFF 2</td><td style="text-align:left;"><a href="https://docs.oasis-open.org/xliff/xliff-core/v2.0/cos01/xliff-core-v2.0-cos01.html" title="XLIFF Version 2.0 | Oasis Open Docs" target="_blank" rel="noreferrer">XML Localization Interchange File Format, version 2</a></td><td style="text-align:left;"><code>.xlf</code></td></tr><tr><td style="text-align:left;">XMB</td><td style="text-align:left;"><a href="https://cldr.unicode.org/development/development-process/design-proposals/xmb" title="XMB | CLDR - Unicode Common Locale Data Repository | Unicode" target="_blank" rel="noreferrer">XML Message Bundle</a></td><td style="text-align:left;"><code>.xmb</code> (<code>.xtb</code>)</td></tr></tbody></table><p>Specify the translation format explicitly with the <code>--format</code> command option.</p><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>The XMB format generates <code>.xmb</code> source language files, but uses<code>.xtb</code> translation files.</p></div><h4 id="extract-i18n-format-example" tabindex="-1"><code>extract-i18n --format</code> example <a class="header-anchor" href="#extract-i18n-format-example" aria-label="Permalink to &quot;\`extract-i18n --format\` example&quot;">​</a></h4><p>The following example demonstrates several translation formats.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extract-i18n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format=xlf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extract-i18n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format=xlf2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extract-i18n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format=xmb</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extract-i18n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format=json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extract-i18n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format=arb</span></span></code></pre></div><h3 id="change-the-source-language-file-name" tabindex="-1">Change the source language file name <a class="header-anchor" href="#change-the-source-language-file-name" aria-label="Permalink to &quot;Change the source language file name&quot;">​</a></h3><p>To change the name of the source language file generated by the extraction tool, use the <code>--out-file</code> command option.</p><h4 id="extract-i18n-out-file-example" tabindex="-1"><code>extract-i18n --out-file</code> example <a class="header-anchor" href="#extract-i18n-out-file-example" aria-label="Permalink to &quot;\`extract-i18n --out-file\` example&quot;">​</a></h4><p>The following example demonstrates naming the output file.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extract-i18n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source.xlf</span></span></code></pre></div><h2 id="create-a-translation-file-for-each-language" tabindex="-1">Create a translation file for each language <a class="header-anchor" href="#create-a-translation-file-for-each-language" aria-label="Permalink to &quot;Create a translation file for each language&quot;">​</a></h2><p>To create a translation file for a locale or language, complete the following actions.</p><ol><li><p><a href="./guide/i18n/translation-files#extract-the-source-language-file" title="Extract the source language file - Work with translation files | Angular">Extract the source language file</a>.</p></li><li><p>Make a copy of the source language file to create a <em>translation</em> file for each language.</p></li><li><p>Rename the <em>translation</em> file to add the locale.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>messages.xlf --&gt; messages.{locale}.xlf</span></span></code></pre></div></li><li><p>Create a new directory at your project root named <code>locale</code>.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>src/locale</span></span></code></pre></div></li><li><p>Move the <em>translation</em> file to the new directory.</p></li><li><p>Send the <em>translation</em> file to your translator.</p></li><li><p>Repeat the above steps for each language you want to add to your application.</p></li></ol><h3 id="extract-i18n-example-for-french" tabindex="-1"><code>extract-i18n</code> example for French <a class="header-anchor" href="#extract-i18n-example-for-french" aria-label="Permalink to &quot;\`extract-i18n\` example for French&quot;">​</a></h3><p>For example, to create a French translation file, complete the following actions.</p><ol><li>Run the <code>extract-i18n</code> command.</li><li>Make a copy of the <code>messages.xlf</code> source language file.</li><li>Rename the copy to <code>messages.fr.xlf</code> for the French language (<code>fr</code>) translation.</li><li>Move the <code>fr</code> translation file to the <code>src/locale</code> directory.</li><li>Send the <code>fr</code> translation file to the translator.</li></ol><h2 id="translate-each-translation-file" tabindex="-1">Translate each translation file <a class="header-anchor" href="#translate-each-translation-file" aria-label="Permalink to &quot;Translate each translation file&quot;">​</a></h2><p>Unless you are fluent in the language and have the time to edit translations, you will likely complete the following steps.</p><ol><li>Send each translation file to a translator.</li><li>The translator uses an XLIFF file editor to complete the following actions. <ol><li>Create the translation.</li><li>Edit the translation.</li></ol></li></ol><h3 id="translation-process-example-for-french" tabindex="-1">Translation process example for French <a class="header-anchor" href="#translation-process-example-for-french" aria-label="Permalink to &quot;Translation process example for French&quot;">​</a></h3><p>To demonstrate the process, review the <code>messages.fr.xlf</code> file in the <a href="./guide/i18n/example" title="Example Angular Internationalization application | Angular">Example Angular Internationalization application</a>. The <a href="./guide/i18n/example" title="Example Angular Internationalization application | Angular">Example Angular Internationalization application</a> includes a French translation for you to edit without a special XLIFF editor or knowledge of French.</p><p>The following actions describe the translation process for French.</p><ol><li><p>Open <code>messages.fr.xlf</code> and find the first <code>&lt;trans-unit&gt;</code> element. This is a <em>translation unit</em>, also known as a <em>text node</em>, that represents the translation of the <code>&lt;h1&gt;</code> greeting tag that was previously marked with the <code>i18n</code> attribute.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;trans-unit id=&quot;introductionHeader&quot; datatype=&quot;html&quot;&gt;</span></span>
<span class="line"><span>  &lt;source&gt;Hello i18n!&lt;/source&gt;</span></span>
<span class="line"><span>  &lt;note priority=&quot;1&quot; from=&quot;description&quot;&gt;An introduction header for this sample&lt;/note&gt;</span></span>
<span class="line"><span>  &lt;note priority=&quot;1&quot; from=&quot;meaning&quot;&gt;User welcome&lt;/note&gt;</span></span>
<span class="line"><span>&lt;/trans-unit&gt;</span></span></code></pre></div><p>The <code>id=&quot;introductionHeader&quot;</code> is a <a href="./guide/i18n/manage-marked-text" title="Manage marked text with custom IDs | Angular">custom ID</a>, but without the <code>@@</code> prefix required in the source HTML.</p></li><li><p>Duplicate the <code>&lt;source&gt;... &lt;/source&gt;</code> element in the text node, rename it to <code>target</code>, and then replace the content with the French text.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;trans-unit id=&quot;introductionHeader&quot; datatype=&quot;html&quot;&gt;</span></span>
<span class="line"><span>  &lt;source&gt;Hello i18n!&lt;/source&gt;</span></span>
<span class="line"><span>  &lt;target&gt;Bonjour i18n !&lt;/target&gt;</span></span>
<span class="line"><span>  &lt;note priority=&quot;1&quot; from=&quot;description&quot;&gt;An introduction header for this sample&lt;/note&gt;</span></span>
<span class="line"><span>  &lt;note priority=&quot;1&quot; from=&quot;meaning&quot;&gt;User welcome&lt;/note&gt;</span></span>
<span class="line"><span>&lt;/trans-unit&gt;</span></span></code></pre></div><p>In a more complex translation, the information and context in the <a href="./guide/i18n/prepare#add-helpful-descriptions-and-meanings" title="Add helpful descriptions and meanings - Prepare component for translation | Angular">description and meaning elements</a> help you choose the right words for translation.</p></li><li><p>Translate the other text nodes. The following example displays the way to translate.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;trans-unit id=&quot;ba0cc104d3d69bf669f97b8d96a4c5d8d9559aa3&quot; datatype=&quot;html&quot;&gt;</span></span>
<span class="line"><span>  &lt;source&gt;I don&amp;apos;t output any element&lt;/source&gt;</span></span>
<span class="line"><span>  &lt;target&gt;Je n&#39;affiche aucun élément&lt;/target&gt;</span></span>
<span class="line"><span>&lt;/trans-unit&gt;</span></span>
<span class="line"><span>&lt;trans-unit id=&quot;701174153757adf13e7c24a248c8a873ac9f5193&quot; datatype=&quot;html&quot;&gt;</span></span>
<span class="line"><span>  &lt;source&gt;Angular logo&lt;/source&gt;</span></span>
<span class="line"><span>  &lt;target&gt;Logo d&#39;Angular&lt;/target&gt;</span></span>
<span class="line"><span>&lt;/trans-unit&gt;</span></span></code></pre></div></li></ol><div class="warning custom-block"><p class="custom-block-title">IMPORTANT</p><p>Don&#39;t change the IDs for translation units. Each <code>id</code> attribute is generated by Angular and depends on the content of the component text and the assigned meaning.</p></div><p>If you change either the text or the meaning, then the <code>id</code> attribute changes. For more about managing text updates and IDs, see <a href="./guide/i18n/manage-marked-text" title="Manage marked text with custom IDs | Angular">custom IDs</a>.</p><h2 id="translate-plurals" tabindex="-1">Translate plurals <a class="header-anchor" href="#translate-plurals" aria-label="Permalink to &quot;Translate plurals&quot;">​</a></h2><p>Add or remove plural cases as needed for each language.</p><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>For language plural rules, see <a href="https://cldr.unicode.org/index/cldr-spec/plural-rules" title="Language Plural Rules - CLDR Charts | Unicode | GitHub" target="_blank" rel="noreferrer">CLDR plural rules</a>.</p></div><h3 id="minute-plural-example" tabindex="-1"><code>minute</code> <code>plural</code> example <a class="header-anchor" href="#minute-plural-example" aria-label="Permalink to &quot;\`minute\` \`plural\` example&quot;">​</a></h3><p>To translate a <code>plural</code>, translate the ICU format match values.</p><ul><li><code>just now</code></li><li><code>one minute ago</code></li><li><code>&lt;x id=&quot;INTERPOLATION&quot; equiv-text=&quot;{{minutes}}&quot;/&gt; minutes ago</code></li></ul><p>The following example displays the way to translate.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;trans-unit id=&quot;5a134dee893586d02bffc9611056b9cadf9abfad&quot; datatype=&quot;html&quot;&gt;</span></span>
<span class="line"><span>  &lt;source&gt;{VAR_PLURAL, plural, =0 {just now} =1 {one minute ago} other {&lt;x id=&quot;INTERPOLATION&quot; equiv-text=&quot;{{minutes}}&quot;/&gt; minutes ago} }&lt;/source&gt;</span></span>
<span class="line"><span>  &lt;target&gt;{VAR_PLURAL, plural, =0 {à l&#39;instant} =1 {il y a une minute} other {il y a &lt;x id=&quot;INTERPOLATION&quot; equiv-text=&quot;{{minutes}}&quot;/&gt; minutes} }&lt;/target&gt;</span></span>
<span class="line"><span>&lt;/trans-unit&gt;</span></span></code></pre></div><h2 id="translate-alternate-expressions" tabindex="-1">Translate alternate expressions <a class="header-anchor" href="#translate-alternate-expressions" aria-label="Permalink to &quot;Translate alternate expressions&quot;">​</a></h2><p>Angular also extracts alternate <code>select</code> ICU expressions as separate translation units.</p><h3 id="gender-select-example" tabindex="-1"><code>gender</code> <code>select</code> example <a class="header-anchor" href="#gender-select-example" aria-label="Permalink to &quot;\`gender\` \`select\` example&quot;">​</a></h3><p>The following example displays a <code>select</code> ICU expression in the component template.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">span</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> i18n</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;The author is {gender, select, male {male} female {female} other {other}}&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">span</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>In this example, Angular extracts the expression into two translation units. The first contains the text outside of the <code>select</code> clause, and uses a placeholder for <code>select</code> (<code>&lt;x id=&quot;ICU&quot;&gt;</code>):</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;trans-unit id=&quot;f99f34ac9bd4606345071bd813858dec29f3b7d1&quot; datatype=&quot;html&quot;&gt;</span></span>
<span class="line"><span>  &lt;source&gt;The author is &lt;x id=&quot;ICU&quot; equiv-text=&quot;{gender, select, male {...} female {...} other {...}}&quot;/&gt;&lt;/source&gt;</span></span>
<span class="line"><span>  &lt;target&gt;L&#39;auteur est &lt;x id=&quot;ICU&quot; equiv-text=&quot;{gender, select, male {...} female {...} other {...}}&quot;/&gt;&lt;/target&gt;</span></span>
<span class="line"><span>&lt;/trans-unit&gt;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">IMPORTANT</p><p>When you translate the text, move the placeholder if necessary, but don&#39;t remove it. If you remove the placeholder, the ICU expression is removed from your translated application.</p></div><p>The following example displays the second translation unit that contains the <code>select</code> clause.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;trans-unit id=&quot;eff74b75ab7364b6fa888f1cbfae901aaaf02295&quot; datatype=&quot;html&quot;&gt;</span></span>
<span class="line"><span>  &lt;source&gt;{VAR_SELECT, select, male {male} female {female} other {other} }&lt;/source&gt;</span></span>
<span class="line"><span>  &lt;target&gt;{VAR_SELECT, select, male {un homme} female {une femme} other {autre} }&lt;/target&gt;</span></span>
<span class="line"><span>&lt;/trans-unit&gt;</span></span></code></pre></div><p>The following example displays both translation units after translation is complete.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;trans-unit id=&quot;f99f34ac9bd4606345071bd813858dec29f3b7d1&quot; datatype=&quot;html&quot;&gt;</span></span>
<span class="line"><span>  &lt;source&gt;The author is &lt;x id=&quot;ICU&quot; equiv-text=&quot;{gender, select, male {...} female {...} other {...}}&quot;/&gt;&lt;/source&gt;</span></span>
<span class="line"><span>  &lt;target&gt;L&#39;auteur est &lt;x id=&quot;ICU&quot; equiv-text=&quot;{gender, select, male {...} female {...} other {...}}&quot;/&gt;&lt;/target&gt;</span></span>
<span class="line"><span>&lt;/trans-unit&gt;</span></span>
<span class="line"><span>&lt;trans-unit id=&quot;eff74b75ab7364b6fa888f1cbfae901aaaf02295&quot; datatype=&quot;html&quot;&gt;</span></span>
<span class="line"><span>  &lt;source&gt;{VAR_SELECT, select, male {male} female {female} other {other} }&lt;/source&gt;</span></span>
<span class="line"><span>  &lt;target&gt;{VAR_SELECT, select, male {un homme} female {une femme} other {autre} }&lt;/target&gt;</span></span>
<span class="line"><span>&lt;/trans-unit&gt;</span></span></code></pre></div><h2 id="translate-nested-expressions" tabindex="-1">Translate nested expressions <a class="header-anchor" href="#translate-nested-expressions" aria-label="Permalink to &quot;Translate nested expressions&quot;">​</a></h2><p>Angular treats a nested expression in the same manner as an alternate expression. Angular extracts the expression into two translation units.</p><h3 id="nested-plural-example" tabindex="-1">Nested <code>plural</code> example <a class="header-anchor" href="#nested-plural-example" aria-label="Permalink to &quot;Nested \`plural\` example&quot;">​</a></h3><p>The following example displays the first translation unit that contains the text outside of the nested expression.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;trans-unit id=&quot;972cb0cf3e442f7b1c00d7dab168ac08d6bdf20c&quot; datatype=&quot;html&quot;&gt;</span></span>
<span class="line"><span>  &lt;source&gt;Updated: &lt;x id=&quot;ICU&quot; equiv-text=&quot;{minutes, plural, =0 {...} =1 {...} other {...}}&quot;/&gt;&lt;/source&gt;</span></span>
<span class="line"><span>  &lt;target&gt;Mis à jour: &lt;x id=&quot;ICU&quot; equiv-text=&quot;{minutes, plural, =0 {...} =1 {...} other {...}}&quot;/&gt;&lt;/target&gt;</span></span>
<span class="line"><span>&lt;/trans-unit&gt;</span></span></code></pre></div><p>The following example displays the second translation unit that contains the complete nested expression.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;trans-unit id=&quot;7151c2e67748b726f0864fc443861d45df21d706&quot; datatype=&quot;html&quot;&gt;</span></span>
<span class="line"><span>  &lt;source&gt;{VAR_PLURAL, plural, =0 {just now} =1 {one minute ago} other {&lt;x id=&quot;INTERPOLATION&quot; equiv-text=&quot;{{minutes}}&quot;/&gt; minutes ago by {VAR_SELECT, select, male {male} female {female} other {other} }} }&lt;/source&gt;</span></span>
<span class="line"><span>  &lt;target&gt;{VAR_PLURAL, plural, =0 {à l&#39;instant} =1 {il y a une minute} other {il y a &lt;x id=&quot;INTERPOLATION&quot; equiv-text=&quot;{{minutes}}&quot;/&gt; minutes par {VAR_SELECT, select, male {un homme} female {une femme} other {autre} }} }&lt;/target&gt;</span></span>
<span class="line"><span>&lt;/trans-unit&gt;</span></span></code></pre></div><p>The following example displays both translation units after translating.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;trans-unit id=&quot;972cb0cf3e442f7b1c00d7dab168ac08d6bdf20c&quot; datatype=&quot;html&quot;&gt;</span></span>
<span class="line"><span>  &lt;source&gt;Updated: &lt;x id=&quot;ICU&quot; equiv-text=&quot;{minutes, plural, =0 {...} =1 {...} other {...}}&quot;/&gt;&lt;/source&gt;</span></span>
<span class="line"><span>  &lt;target&gt;Mis à jour: &lt;x id=&quot;ICU&quot; equiv-text=&quot;{minutes, plural, =0 {...} =1 {...} other {...}}&quot;/&gt;&lt;/target&gt;</span></span>
<span class="line"><span>&lt;/trans-unit&gt;</span></span>
<span class="line"><span>&lt;trans-unit id=&quot;7151c2e67748b726f0864fc443861d45df21d706&quot; datatype=&quot;html&quot;&gt;</span></span>
<span class="line"><span>  &lt;source&gt;{VAR_PLURAL, plural, =0 {just now} =1 {one minute ago} other {&lt;x id=&quot;INTERPOLATION&quot; equiv-text=&quot;{{minutes}}&quot;/&gt; minutes ago by {VAR_SELECT, select, male {male} female {female} other {other} }} }&lt;/source&gt;</span></span>
<span class="line"><span>  &lt;target&gt;{VAR_PLURAL, plural, =0 {à l&#39;instant} =1 {il y a une minute} other {il y a &lt;x id=&quot;INTERPOLATION&quot; equiv-text=&quot;{{minutes}}&quot;/&gt; minutes par {VAR_SELECT, select, male {un homme} female {une femme} other {autre} }} }&lt;/target&gt;</span></span>
<span class="line"><span>&lt;/trans-unit&gt;</span></span></code></pre></div><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="/guide/i18n/merge">Merge translations into the app</a></li></ul>`,76)]))}const g=e(l,[["render",i]]);export{h as __pageData,g as default};
